class Solution {
public:
    vector<int> twoSum(vector<int>& numbers, int target) {
        int left = 0, right = numbers.size() - 1;
        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum == target) {
                // Found the pair — return 1-indexed positions
                return {left + 1, right + 1};
            } else if (sum < target) {
                left++;  // need a bigger sum, move left pointer right
            } else {
                right--; // need a smaller sum, move right pointer left
            }
        }
        return {}; // no solution found
    }
};

class Solution {
public:
    bool isPalindrome(string s) {
        int left = 0, right = s.size() - 1;
        while (left < right) {
            // Skip non-alphanumeric characters from both ends
            while (left < right && !isalnum(s[left])) left++;
            while (left < right && !isalnum(s[right])) right--;
            if (tolower(s[left]) != tolower(s[right])) return false;
            left++;
            right--;
        }
        return true;
    }
};

class Solution {
public:
    int maxArea(vector<int>& height) {
        int left = 0, right = height.size() - 1;
        int maxWater = 0;
        while (left < right) {
            int width = right - left;
            int h = min(height[left], height[right]); // limited by shorter wall
            maxWater = max(maxWater, width * h);
            // Move the pointer at the shorter wall — moving the taller one
            // can never increase area since width only shrinks either way
            if (height[left] < height[right]) left++;
            else right--;
        }
        return maxWater;
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        vector<vector<int>> result;
        sort(nums.begin(), nums.end()); // sorting enables the two-pointer scan
        int n = nums.size();
        for (int i = 0; i < n - 2; i++) {
            if (nums[i] > 0) break;                       // smallest is positive -> no triplet possible
            if (i > 0 && nums[i] == nums[i - 1]) continue; // skip duplicate anchor
            int left = i + 1, right = n - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum == 0) {
                    result.push_back({nums[i], nums[left], nums[right]});
                    left++; right--;
                    // skip duplicate values to avoid duplicate triplets
                    while (left < right && nums[left] == nums[left - 1]) left++;
                    while (left < right && nums[right] == nums[right + 1]) right--;
                } else if (sum < 0) {
                    left++;  // need a larger sum
                } else {
                    right--; // need a smaller sum
                }
            }
        }
        return result;
    }
};

class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int closestSum = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1, right = n - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                // Update closest sum if current sum is nearer to target
                if (abs(sum - target) < abs(closestSum - target)) closestSum = sum;
                if (sum == target) return sum; // exact match, can't get any closer
                else if (sum < target) left++;
                else right--;
            }
        }
        return closestSum;
    }
};

class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        vector<vector<int>> result;
        sort(nums.begin(), nums.end());
        int n = nums.size();
        for (int i = 0; i < n - 3; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue; // skip duplicate 1st anchor
            for (int j = i + 1; j < n - 2; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue; // skip duplicate 2nd anchor
                // use long long to avoid overflow while summing
                long long twoSumTarget = (long long)target - nums[i] - nums[j];
                int left = j + 1, right = n - 1;
                while (left < right) {
                    long long sum = (long long)nums[left] + nums[right];
                    if (sum == twoSumTarget) {
                        result.push_back({nums[i], nums[j], nums[left], nums[right]});
                        left++; right--;
                        while (left < right && nums[left] == nums[left - 1]) left++;
                        while (left < right && nums[right] == nums[right + 1]) right--;
                    } else if (sum < twoSumTarget) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        return result;
    }
};

class Solution {
public:
    int trap(vector<int>& height) {
        int left = 0, right = height.size() - 1;
        int leftMax = 0, rightMax = 0, water = 0;
        while (left < right) {
            if (height[left] < height[right]) {
                // right side has a taller boundary, so left side is the bottleneck
                if (height[left] >= leftMax) leftMax = height[left];
                else water += leftMax - height[left]; // water trapped above this bar
                left++;
            } else {
                if (height[right] >= rightMax) rightMax = height[right];
                else water += rightMax - height[right];
                right--;
            }
        }
        return water;
    }
};

class Solution {
public:
    vector<int> sortedSquares(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n);
        int left = 0, right = n - 1;
        // fill result from the back — the largest square always sits at an extreme end
        for (int k = n - 1; k >= 0; k--) {
            int leftSq = nums[left] * nums[left];
            int rightSq = nums[right] * nums[right];
            if (leftSq > rightSq) {
                result[k] = leftSq;
                left++;
            } else {
                result[k] = rightSq;
                right--;
            }
        }
        return result;
    }
};

class Solution {
public:
    void reverseString(vector<char>& s) {
        int left = 0, right = s.size() - 1;
        while (left < right) {
            swap(s[left], s[right]);
            left++; right--;
        }
    }
};

class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if (nums.empty()) return 0;
        int slow = 0; // slow marks the last confirmed position of a unique element
        for (int fast = 1; fast < nums.size(); fast++) {
            if (nums[fast] != nums[slow]) {
                slow++;
                nums[slow] = nums[fast]; // place newly found unique element
            }
        }
        return slow + 1; // length of the unique portion
    }
};

class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int slow = 0; // slow tracks the next position to place a non-zero element
        for (int fast = 0; fast < nums.size(); fast++) {
            if (nums[fast] != 0) {
                swap(nums[slow], nums[fast]); // bring non-zero forward, push zero back
                slow++;
            }
        }
    }
};

class Solution {
public:
    void sortColors(vector<int>& nums) {
        int low = 0, mid = 0, high = nums.size() - 1;
        // Invariant: [0, low) = 0s, [low, mid) = 1s, (high, end] = 2s
        while (mid <= high) {
            if (nums[mid] == 0) {
                swap(nums[low], nums[mid]);
                low++; mid++;
            } else if (nums[mid] == 1) {
                mid++; // 1 is already in its correct region
            } else {
                swap(nums[mid], nums[high]);
                high--; // don't advance mid — must recheck the swapped-in value
            }
        }
    }
};

class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1; // fill nums1 from the back
        while (j >= 0) {
            // place the larger current element at the last free slot
            if (i >= 0 && nums1[i] > nums2[j]) nums1[k--] = nums1[i--];
            else nums1[k--] = nums2[j--];
        }
    }
};

class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        sort(nums1.begin(), nums1.end());
        sort(nums2.begin(), nums2.end());
        int i = 0, j = 0;
        vector<int> result;
        while (i < nums1.size() && j < nums2.size()) {
            if (nums1[i] < nums2[j]) i++;
            else if (nums1[i] > nums2[j]) j++;
            else {
                result.push_back(nums1[i]); // common element found
                i++; j++;
            }
        }
        return result;
    }
};

class Solution {
public:
    bool hasCycle(ListNode *head) {
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;        // moves 1 step at a time
            fast = fast->next->next;  // moves 2 steps at a time
            if (slow == fast) return true; // pointers met -> cycle exists
        }
        return false; // fast reached the end -> no cycle
    }
};

class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        ListNode *slow = head, *fast = head;
        // when fast reaches the end, slow lands exactly at the middle
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }
};

class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode *fast = &dummy, *slow = &dummy;
        // advance fast n steps ahead to create a gap of exactly n nodes
        for (int i = 0; i < n; i++) fast = fast->next;
        while (fast->next) {
            fast = fast->next;
            slow = slow->next;
        }
        // slow now sits just before the node that must be removed
        ListNode* toDelete = slow->next;
        slow->next = slow->next->next;
        delete toDelete;
        return dummy.next;
    }
};

class Solution {
public:
    bool isPalindrome(ListNode* head) {
        if (!head || !head->next) return true;

        // Step 1: find the middle using fast/slow pointers
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }

        // Step 2: reverse the second half in-place
        ListNode *prev = nullptr, *curr = slow;
        while (curr) {
            ListNode* next = curr->next;
            curr->next = prev;
            prev = curr;
            curr = next;
        }

        // Step 3: compare first half against the reversed second half
        ListNode *left = head, *right = prev;
        while (right) { // right half may be shorter for odd-length lists
            if (left->val != right->val) return false;
            left = left->next;
            right = right->next;
        }
        return true;
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int left = 0, sum = 0, minLen = INT_MAX;
        for (int right = 0; right < nums.size(); right++) {
            sum += nums[right]; // expand window on the right
            // shrink window from the left while it still satisfies the target
            while (sum >= target) {
                minLen = min(minLen, right - left + 1);
                sum -= nums[left];
                left++;
            }
        }
        return minLen == INT_MAX ? 0 : minLen;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        vector<int> lastSeen(256, -1); // last index at which each char was seen
        int left = 0, maxLen = 0;
        for (int right = 0; right < s.size(); right++) {
            // if this char repeats inside the current window, shrink from the left
            if (lastSeen[s[right]] >= left) {
                left = lastSeen[s[right]] + 1;
            }
            lastSeen[s[right]] = right;
            maxLen = max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        int n = nums.size();

        // Build the first window of size k
        long long windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += nums[i];
        }

        long long maxSum = windowSum;

        // Slide the window: remove leftmost element, add new rightmost element
        for (int i = k; i < n; i++) {
            windowSum += nums[i] - nums[i - k];
            maxSum = max(maxSum, windowSum);
        }

        return (double)maxSum / k;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        // Stores the most recent index at which a character was seen
        unordered_map<char, int> lastSeen;
        int left = 0, maxLen = 0;

        for (int right = 0; right < s.size(); right++) {
            char c = s[right];

            // If c was seen before AND that occurrence is inside the current window,
            // shrink the window by moving left just past that occurrence
            if (lastSeen.count(c) && lastSeen[c] >= left) {
                left = lastSeen[c] + 1;
            }

            lastSeen[c] = right;                 // update last seen index
            maxLen = max(maxLen, right - left + 1);
        }

        return maxLen;
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size();
        int left = 0;
        long long windowSum = 0;
        int minLen = INT_MAX;

        for (int right = 0; right < n; right++) {
            windowSum += nums[right];            // expand window on the right

            // Shrink from the left as long as the sum condition is still satisfied,
            // trying to find a smaller valid window
            while (windowSum >= target) {
                minLen = min(minLen, right - left + 1);
                windowSum -= nums[left];
                left++;
            }
        }

        return (minLen == INT_MAX) ? 0 : minLen;
    }
};

class Solution {
public:
    int characterReplacement(string s, int k) {
        vector<int> freq(26, 0);
        int left = 0, maxFreq = 0, maxLen = 0;

        for (int right = 0; right < s.size(); right++) {
            freq[s[right] - 'A']++;
            // Track the highest frequency of any single character seen so far
            // in the current window (it only ever needs to grow, never shrink,
            // because a stale maxFreq can't make the window invalid again)
            maxFreq = max(maxFreq, freq[s[right] - 'A']);

            int windowSize = right - left + 1;

            // If (window - most frequent char) > k, we'd need more than k
            // replacements to make the window uniform -> shrink it
            if (windowSize - maxFreq > k) {
                freq[s[left] - 'A']--;
                left++;
            }

            maxLen = max(maxLen, right - left + 1);
        }

        return maxLen;
    }
};

class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        int n1 = s1.size(), n2 = s2.size();
        if (n1 > n2) return false;

        vector<int> need(26, 0), window(26, 0);
        for (char c : s1) need[c - 'a']++;

        // Build the first window of size n1
        for (int i = 0; i < n1; i++) window[s2[i] - 'a']++;
        if (window == need) return true;

        // Slide the window one character at a time
        for (int i = n1; i < n2; i++) {
            window[s2[i] - 'a']++;               // add new char entering window
            window[s2[i - n1] - 'a']--;          // remove char leaving window

            if (window == need) return true;     // frequencies match -> permutation found
        }

        return false;
    }
};

class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        vector<int> result;
        int n = s.size(), m = p.size();
        if (m > n) return result;

        vector<int> need(26, 0), window(26, 0);
        for (char c : p) need[c - 'a']++;

        for (int i = 0; i < n; i++) {
            window[s[i] - 'a']++;                // extend window to include s[i]

            // Once window exceeds size m, remove the leftmost element
            if (i >= m) {
                window[s[i - m] - 'a']--;
            }

            // Window is exactly size m and its frequency matches p's -> anagram found
            if (i >= m - 1 && window == need) {
                result.push_back(i - m + 1);
            }
        }

        return result;
    }
};

class Solution {
public:
    string minWindow(string s, string t) {
        if (s.empty() || t.empty()) return "";

        unordered_map<char, int> need;
        for (char c : t) need[c]++;

        unordered_map<char, int> window;
        int required = need.size();   // number of unique chars that must be satisfied
        int formed = 0;               // number of unique chars currently satisfied

        int left = 0, minLen = INT_MAX, minStart = 0;

        for (int right = 0; right < s.size(); right++) {
            char c = s[right];
            window[c]++;

            // If this char's count now exactly matches what's needed, one more
            // requirement is "formed"
            if (need.count(c) && window[c] == need[c]) {
                formed++;
            }

            // While window satisfies all requirements, try to shrink it from left
            while (formed == required) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }

                char leftChar = s[left];
                window[leftChar]--;
                // Removing this char breaks a requirement -> stop shrinking after this
                if (need.count(leftChar) && window[leftChar] < need[leftChar]) {
                    formed--;
                }
                left++;
            }
        }

        return (minLen == INT_MAX) ? "" : s.substr(minStart, minLen);
    }
};

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        deque<int> dq;   // stores indices; nums[dq.front()] is always the current max
        vector<int> result;

        for (int i = 0; i < nums.size(); i++) {
            // Remove indices that have fallen out of the window from the front
            if (!dq.empty() && dq.front() <= i - k) {
                dq.pop_front();
            }

            // Maintain decreasing order: pop smaller values from the back since
            // they can never be the max while nums[i] is still in the window
            while (!dq.empty() && nums[dq.back()] < nums[i]) {
                dq.pop_back();
            }

            dq.push_back(i);

            // Once the first full window is formed, record the max (front of deque)
            if (i >= k - 1) {
                result.push_back(nums[dq.front()]);
            }
        }

        return result;
    }
};

class Solution {
public:
    int totalFruit(vector<int>& fruits) {
        unordered_map<int, int> basket;   // fruit type -> count in current window
        int left = 0, maxFruits = 0;

        for (int right = 0; right < fruits.size(); right++) {
            basket[fruits[right]]++;

            // More than 2 fruit types in the window -> shrink from left until
            // we're back down to 2 types
            while (basket.size() > 2) {
                basket[fruits[left]]--;
                if (basket[fruits[left]] == 0) {
                    basket.erase(fruits[left]);
                }
                left++;
            }

            maxFruits = max(maxFruits, right - left + 1);
        }

        return maxFruits;
    }
};

class Solution {
public:
    int longestOnes(vector<int>& nums, int k) {
        int left = 0, zeroCount = 0, maxLen = 0;

        for (int right = 0; right < nums.size(); right++) {
            if (nums[right] == 0) zeroCount++;

            // Too many zeros for our flip budget -> shrink from the left
            // until the window is valid again
            while (zeroCount > k) {
                if (nums[left] == 0) zeroCount--;
                left++;
            }

            maxLen = max(maxLen, right - left + 1);
        }

        return maxLen;
    }
};

class Solution {
public:
    int numSubarrayProductLessThanK(vector<int>& nums, int k) {
        if (k <= 1) return 0;   // product of positive ints is always >= 1

        int left = 0;
        long long product = 1;
        int count = 0;

        for (int right = 0; right < nums.size(); right++) {
            product *= nums[right];

            // Shrink from the left while product is too big
            while (product >= k) {
                product /= nums[left];
                left++;
            }

            // Every subarray ending at `right` and starting anywhere in
            // [left, right] is valid -> that's (right - left + 1) new subarrays
            count += right - left + 1;
        }

        return count;
    }
};

class Solution {
public:
    int maxVowels(string s, int k) {
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };

        int count = 0;
        // Build first window
        for (int i = 0; i < k; i++) {
            count += isVowel(s[i]);
        }

        int maxCount = count;

        // Slide: add incoming char, remove outgoing char
        for (int i = k; i < s.size(); i++) {
            count += isVowel(s[i]);
            count -= isVowel(s[i - k]);
            maxCount = max(maxCount, count);
        }

        return maxCount;
    }
};

class Solution {
public:
    int longestSubarray(vector<int>& nums) {
        int left = 0, zeroCount = 0, maxLen = 0;

        for (int right = 0; right < nums.size(); right++) {
            if (nums[right] == 0) zeroCount++;

            // Allow at most one zero in the window (that's the element we "delete")
            while (zeroCount > 1) {
                if (nums[left] == 0) zeroCount--;
                left++;
            }

            // Window length minus 1 because exactly one element must be deleted,
            // even if the window happens to be all 1's
            maxLen = max(maxLen, right - left + 1 - 1);
        }

        return maxLen;
    }
};

class Solution {
public:
    int maxFrequency(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());   // sorting lets us reason about a window
                                           // of elements we raise up to nums[right]
        int left = 0;
        long long budget = 0;    // total increments used to level up window[left..right-1]
        int maxFreq = 1;

        for (int right = 0; right < nums.size(); right++) {
            if (right > 0) {
                // Cost to bring every existing window element up to the new
                // right boundary value: (window size before adding right) * delta
                budget += (long long)(nums[right] - nums[right - 1]) * (right - left);
            }

            // If we've exceeded the operation budget, shrink from the left,
            // refunding the increments that element would have needed
            while (budget > k) {
                budget -= nums[right] - nums[left];
                left++;
            }

            maxFreq = max(maxFreq, right - left + 1);
        }

        return maxFreq;
    }
};

int search(vector<int>& nums, int target) {
    int lo = 0, hi = nums.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoid overflow vs (lo+hi)/2
        if (nums[mid] == target) return mid;
        else if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int searchInsert(vector<int>& nums, int target) {
    int lo = 0, hi = nums.size(); // hi = n, since answer can be "insert at end"
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid; // nums[mid] >= target, mid is a candidate
    }
    return lo;
}

int lowerBound(vector<int>& nums, int target) {
    int lo = 0, hi = nums.size();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

vector<int> searchRange(vector<int>& nums, int target) {
    int first = lowerBound(nums, target);
    if (first == (int)nums.size() || nums[first] != target) return {-1, -1};
    int last = lowerBound(nums, target + 1) - 1;
    return {first, last};
}

int singleNonDuplicate(vector<int>& nums) {
    int lo = 0, hi = nums.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (mid % 2 == 1) mid--;              // force mid to even index
        if (nums[mid] == nums[mid + 1])
            lo = mid + 2;                      // pair intact -> single element is to the right
        else
            hi = mid;                          // pair broken -> single element is at mid or left
    }
    return nums[lo];
}

int search(vector<int>& nums, int target) {
    int lo = 0, hi = nums.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;

        if (nums[lo] <= nums[mid]) {           // left half [lo..mid] is sorted
            if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {                                // right half [mid..hi] is sorted
            if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

bool search(vector<int>& nums, int target) {
    int lo = 0, hi = nums.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return true;

        if (nums[lo] == nums[mid] && nums[mid] == nums[hi]) {
            lo++; hi--;                         // ambiguous, shrink both sides
        } else if (nums[lo] <= nums[mid]) {
            if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {
            if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return false;
}

int findMin(vector<int>& nums) {
    int lo = 0, hi = nums.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] > nums[hi]) lo = mid + 1;   // min is strictly to the right
        else hi = mid;                             // mid could be the min
    }
    return nums[lo];
}

int findPeakElement(vector<int>& nums) {
    int lo = 0, hi = nums.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < nums[mid + 1]) lo = mid + 1;  // peak is to the right
        else hi = mid;                                 // mid could be the peak
    }
    return lo;
}

int peakIndexInMountainArray(vector<int>& arr) {
    int lo = 0, hi = arr.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] < arr[mid + 1]) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

long long hoursNeeded(vector<int>& piles, int k) {
    long long hours = 0;
    for (int p : piles) hours += (p + k - 1) / k;   // ceil(p / k)
    return hours;
}

int minEatingSpeed(vector<int>& piles, int h) {
    int lo = 1, hi = *max_element(piles.begin(), piles.end());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (hoursNeeded(piles, mid) <= h) hi = mid;  // feasible, try slower speed
        else lo = mid + 1;                            // too slow, need more speed
    }
    return lo;
}

int daysNeeded(vector<int>& weights, int cap) {
    int days = 1, curr = 0;
    for (int w : weights) {
        if (curr + w > cap) { days++; curr = 0; }    // start a new day
        curr += w;
    }
    return days;
}

int shipWithinDays(vector<int>& weights, int days) {
    int lo = *max_element(weights.begin(), weights.end());
    int hi = accumulate(weights.begin(), weights.end(), 0);
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (daysNeeded(weights, mid) <= days) hi = mid;  // feasible, try smaller capacity
        else lo = mid + 1;
    }
    return lo;
}

int piecesNeeded(vector<int>& nums, long long maxSum) {
    int pieces = 1; long long curr = 0;
    for (int n : nums) {
        if (curr + n > maxSum) { pieces++; curr = 0; }
        curr += n;
    }
    return pieces;
}

int splitArray(vector<int>& nums, int m) {
    long long lo = *max_element(nums.begin(), nums.end());
    long long hi = accumulate(nums.begin(), nums.end(), 0LL);
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (piecesNeeded(nums, mid) <= m) hi = mid;   // fits in <= m pieces, try smaller sum
        else lo = mid + 1;
    }
    return (int)lo;
}

int studentsNeeded(vector<int>& pages, int maxPages) {
    int students = 1; long long curr = 0;
    for (int p : pages) {
        if (p > maxPages) return INT_MAX;             // single book too big, infeasible
        if (curr + p > maxPages) { students++; curr = 0; }
        curr += p;
    }
    return students;
}

int findPages(vector<int>& pages, int m) {
    if ((int)pages.size() < m) return -1;              // can't give every student a book
    int lo = *max_element(pages.begin(), pages.end());
    int hi = accumulate(pages.begin(), pages.end(), 0);
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (studentsNeeded(pages, mid) <= m) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

bool canPlace(vector<int>& stalls, int cows, int minDist) {
    int count = 1, last = stalls[0];              // place first cow at first stall
    for (size_t i = 1; i < stalls.size(); i++) {
        if (stalls[i] - last >= minDist) {
            count++;
            last = stalls[i];
        }
    }
    return count >= cows;
}

int aggressiveCows(vector<int>& stalls, int cows) {
    sort(stalls.begin(), stalls.end());
    int lo = 1, hi = stalls.back() - stalls.front();
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;          // bias up: we want the largest feasible distance
        if (canPlace(stalls, cows, mid)) lo = mid; // feasible, try to push distance larger
        else hi = mid - 1;
    }
    return lo;
}

bool canPlace(vector<int>& position, int m, int minDist) {
    int count = 1, last = position[0];
    for (size_t i = 1; i < position.size(); i++) {
        if (position[i] - last >= minDist) {
            count++;
            last = position[i];
        }
    }
    return count >= m;
}

int maxDistance(vector<int>& position, int m) {
    sort(position.begin(), position.end());
    int lo = 1, hi = position.back() - position.front();
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        if (canPlace(position, m, mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

bool searchMatrix(vector<vector<int>>& matrix, int target) {
    int m = matrix.size(), n = matrix[0].size();
    int lo = 0, hi = m * n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        int val = matrix[mid / n][mid % n];       // map 1D index -> 2D coordinate
        if (val == target) return true;
        else if (val < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return false;
}

bool searchMatrix(vector<vector<int>>& matrix, int target) {
    int row = 0, col = matrix[0].size() - 1;       // start top-right
    while (row < (int)matrix.size() && col >= 0) {
        if (matrix[row][col] == target) return true;
        else if (matrix[row][col] > target) col--;  // eliminate this column
        else row++;                                   // eliminate this row
    }
    return false;
}

double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
    if (nums1.size() > nums2.size()) return findMedianSortedArrays(nums2, nums1); // search smaller array

    int m = nums1.size(), n = nums2.size();
    int lo = 0, hi = m;
    int total = m + n, half = (total + 1) / 2;

    while (lo <= hi) {
        int cut1 = lo + (hi - lo) / 2;           // partition index in nums1
        int cut2 = half - cut1;                   // forced partition index in nums2

        int left1  = (cut1 == 0) ? INT_MIN : nums1[cut1 - 1];
        int right1 = (cut1 == m) ? INT_MAX : nums1[cut1];
        int left2  = (cut2 == 0) ? INT_MIN : nums2[cut2 - 1];
        int right2 = (cut2 == n) ? INT_MAX : nums2[cut2];

        if (left1 <= right2 && left2 <= right1) {          // valid partition
            if (total % 2 == 0)
                return (max(left1, left2) + min(right1, right2)) / 2.0;
            else
                return max(left1, left2);
        } else if (left1 > right2) {
            hi = cut1 - 1;                        // cut1 too far right, move left
        } else {
            lo = cut1 + 1;                        // cut1 too far left, move right
        }
    }
    return 0.0; // unreachable for valid input
}

int countLessEqual(vector<vector<int>>& matrix, int mid) {
    int n = matrix.size();
    int count = 0, row = n - 1, col = 0;           // start bottom-left
    while (row >= 0 && col < n) {
        if (matrix[row][col] <= mid) {
            count += row + 1;                       // whole column up to `row` qualifies
            col++;
        } else {
            row--;
        }
    }
    return count;
}

int kthSmallest(vector<vector<int>>& matrix, int k) {
    int n = matrix.size();
    int lo = matrix[0][0], hi = matrix[n - 1][n - 1];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countLessEqual(matrix, mid) < k) lo = mid + 1;  // not enough elements <= mid
        else hi = mid;                                        // mid could be the answer
    }
    return lo;
}

int mySqrt(int x) {
    if (x < 2) return x;
    long long lo = 1, hi = x;
    while (lo < hi) {
        long long mid = lo + (hi - lo + 1) / 2;    // bias up: want the largest feasible root
        if (mid * mid <= x) lo = mid;               // feasible, try larger
        else hi = mid - 1;
    }
    return (int)lo;
}

class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> res;
        vector<int> path;
        backtrack(nums, 0, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {
        // every partial 'path' is itself a valid subset -> record it here, not just at leaves
        res.push_back(path);

        for (int i = start; i < nums.size(); i++) {
            path.push_back(nums[i]);              // choose
            backtrack(nums, i + 1, path, res);     // explore
            path.pop_back();                       // un-choose (backtrack)
        }
    }
};

class Solution {
public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        sort(nums.begin(), nums.end());   // group duplicates together
        vector<vector<int>> res;
        vector<int> path;
        backtrack(nums, 0, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {
        res.push_back(path);
        for (int i = start; i < nums.size(); i++) {
            // skip duplicate values at the SAME recursion depth
            // (i > start, not i > 0 — start is fixed per call, so this only
            // blocks re-picking a value we already tried at this level)
            if (i > start && nums[i] == nums[i - 1]) continue;
            path.push_back(nums[i]);
            backtrack(nums, i + 1, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end()); // enables early break/pruning
        vector<vector<int>> res;
        vector<int> path;
        backtrack(candidates, target, 0, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& cand, int remain, int start,
                    vector<int>& path, vector<vector<int>>& res) {
        if (remain == 0) { res.push_back(path); return; }

        for (int i = start; i < cand.size(); i++) {
            if (cand[i] > remain) break;          // sorted -> everything after is too big too
            path.push_back(cand[i]);
            // pass i (NOT i + 1): the same element can be reused
            backtrack(cand, remain - cand[i], i, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<vector<int>> res;
        vector<int> path;
        backtrack(candidates, target, 0, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& cand, int remain, int start,
                    vector<int>& path, vector<vector<int>>& res) {
        if (remain == 0) { res.push_back(path); return; }

        for (int i = start; i < cand.size(); i++) {
            if (cand[i] > remain) break;
            if (i > start && cand[i] == cand[i - 1]) continue; // skip dup at same depth
            path.push_back(cand[i]);
            backtrack(cand, remain - cand[i], i + 1, path, res); // i+1: no reuse
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> combinationSum3(int k, int n) {
        vector<vector<int>> res;
        vector<int> path;
        backtrack(k, n, 1, path, res);
        return res;
    }
private:
    void backtrack(int k, int remain, int start, vector<int>& path, vector<vector<int>>& res) {
        if ((int)path.size() == k) {
            if (remain == 0) res.push_back(path);
            return;
        }
        for (int i = start; i <= 9; i++) {
            if (i > remain) break;                 // digits increase, so rest are too big too
            path.push_back(i);
            backtrack(k, remain - i, i + 1, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> combine(int n, int k) {
        vector<vector<int>> res;
        vector<int> path;
        backtrack(n, k, 1, path, res);
        return res;
    }
private:
    void backtrack(int n, int k, int start, vector<int>& path, vector<vector<int>>& res) {
        if ((int)path.size() == k) { res.push_back(path); return; }

        // prune: if remaining numbers (n - i + 1) can't fill the needed slots, stop early
        for (int i = start; i <= n - (k - (int)path.size()) + 1; i++) {
            path.push_back(i);
            backtrack(n, k, i + 1, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> res;
        vector<int> path;
        vector<bool> used(nums.size(), false);
        backtrack(nums, used, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& nums, vector<bool>& used,
                    vector<int>& path, vector<vector<int>>& res) {
        if (path.size() == nums.size()) {
            res.push_back(path);
            return;
        }
        for (int i = 0; i < nums.size(); i++) {
            if (used[i]) continue;               // element already placed in this path
            used[i] = true;
            path.push_back(nums[i]);
            backtrack(nums, used, path, res);
            path.pop_back();                     // backtrack
            used[i] = false;                      // free it up for other branches
        }
    }
};

class Solution {
public:
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());          // group duplicates
        vector<vector<int>> res;
        vector<int> path;
        vector<bool> used(nums.size(), false);
        backtrack(nums, used, path, res);
        return res;
    }
private:
    void backtrack(vector<int>& nums, vector<bool>& used,
                    vector<int>& path, vector<vector<int>>& res) {
        if (path.size() == nums.size()) {
            res.push_back(path);
            return;
        }
        for (int i = 0; i < nums.size(); i++) {
            if (used[i]) continue;
            // skip duplicate: only allow the FIRST unused copy of an equal value
            // per position. If nums[i-1] is equal but currently NOT used, it means
            // we backtracked past it -> using nums[i] now would produce a permutation
            // identical to one already generated with nums[i-1] in that slot.
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            path.push_back(nums[i]);
            backtrack(nums, used, path, res);
            path.pop_back();
            used[i] = false;
        }
    }
};

class Solution {
public:
    vector<vector<string>> partition(string s) {
        vector<vector<string>> res;
        vector<string> path;
        backtrack(s, 0, path, res);
        return res;
    }
private:
    bool isPalindrome(const string& s, int l, int r) {
        while (l < r) if (s[l++] != s[r--]) return false;
        return true;
    }
    void backtrack(const string& s, int start, vector<string>& path,
                    vector<vector<string>>& res) {
        if (start == (int)s.size()) {
            res.push_back(path);
            return;
        }
        for (int end = start; end < (int)s.size(); end++) {
            if (!isPalindrome(s, start, end)) continue; // prune non-palindromic cuts
            path.push_back(s.substr(start, end - start + 1));
            backtrack(s, end + 1, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<string> restoreIpAddresses(string s) {
        vector<string> res;
        vector<string> path;
        backtrack(s, 0, path, res);
        return res;
    }
private:
    bool isValid(const string& seg) {
        if (seg.empty() || seg.size() > 3) return false;
        if (seg.size() > 1 && seg[0] == '0') return false; // no leading zero
        return stoi(seg) <= 255;
    }
    void backtrack(const string& s, int start, vector<string>& path, vector<string>& res) {
        if (path.size() == 4) {
            if (start == (int)s.size()) {
                string ip = path[0] + "." + path[1] + "." + path[2] + "." + path[3];
                res.push_back(ip);
            }
            return;
        }
        for (int len = 1; len <= 3 && start + len <= (int)s.size(); len++) {
            string seg = s.substr(start, len);
            if (!isValid(seg)) continue;
            path.push_back(seg);
            backtrack(s, start + len, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        int rows = board.size(), cols = board[0].size();
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (dfs(board, word, 0, r, c)) return true;
        return false;
    }
private:
    bool dfs(vector<vector<char>>& board, const string& word, int idx, int r, int c) {
        if (idx == (int)word.size()) return true; // matched entire word
        if (r < 0 || c < 0 || r >= (int)board.size() || c >= (int)board[0].size()
            || board[r][c] != word[idx]) return false;

        char temp = board[r][c];
        board[r][c] = '#';                 // mark visited in-place
        bool found = dfs(board, word, idx + 1, r + 1, c) ||
                     dfs(board, word, idx + 1, r - 1, c) ||
                     dfs(board, word, idx + 1, r, c + 1) ||
                     dfs(board, word, idx + 1, r, c - 1);
        board[r][c] = temp;                // backtrack: restore cell
        return found;
    }
};

class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> res;
        vector<int> queenCol(n, -1);           // queenCol[row] = column of queen in that row
        vector<bool> cols(n, false), diag1(2 * n, false), diag2(2 * n, false);
        backtrack(0, n, queenCol, cols, diag1, diag2, res);
        return res;
    }
private:
    void backtrack(int row, int n, vector<int>& queenCol,
                    vector<bool>& cols, vector<bool>& diag1, vector<bool>& diag2,
                    vector<vector<string>>& res) {
        if (row == n) {
            res.push_back(buildBoard(queenCol, n));
            return;
        }
        for (int col = 0; col < n; col++) {
            int d1 = row - col + n, d2 = row + col;   // normalized diagonal ids
            if (cols[col] || diag1[d1] || diag2[d2]) continue; // conflict, skip
            cols[col] = diag1[d1] = diag2[d2] = true;
            queenCol[row] = col;
            backtrack(row + 1, n, queenCol, cols, diag1, diag2, res);
            cols[col] = diag1[d1] = diag2[d2] = false; // backtrack
            queenCol[row] = -1;
        }
    }
    vector<string> buildBoard(vector<int>& queenCol, int n) {
        vector<string> board(n, string(n, '.'));
        for (int r = 0; r < n; r++) board[r][queenCol[r]] = 'Q';
        return board;
    }
};

class Solution {
public:
    int totalNQueens(int n) {
        vector<bool> cols(n, false), diag1(2 * n, false), diag2(2 * n, false);
        return backtrack(0, n, cols, diag1, diag2);
    }
private:
    int backtrack(int row, int n, vector<bool>& cols, vector<bool>& diag1, vector<bool>& diag2) {
        if (row == n) return 1;
        int count = 0;
        for (int col = 0; col < n; col++) {
            int d1 = row - col + n, d2 = row + col;
            if (cols[col] || diag1[d1] || diag2[d2]) continue;
            cols[col] = diag1[d1] = diag2[d2] = true;
            count += backtrack(row + 1, n, cols, diag1, diag2);
            cols[col] = diag1[d1] = diag2[d2] = false;
        }
        return count;
    }
};

class Solution {
public:
    void solveSudoku(vector<vector<char>>& board) {
        solve(board);
    }
private:
    bool solve(vector<vector<char>>& board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.') continue;
                for (char d = '1'; d <= '9'; d++) {
                    if (!isValid(board, r, c, d)) continue;
                    board[r][c] = d;                  // place digit
                    if (solve(board)) return true;    // propagate success upward
                    board[r][c] = '.';                // backtrack
                }
                return false; // no digit worked here -> dead end, backtrack further up
            }
        }
        return true; // no empty cells left -> solved
    }
    bool isValid(vector<vector<char>>& board, int r, int c, char d) {
        int boxRow = 3 * (r / 3), boxCol = 3 * (c / 3);
        for (int i = 0; i < 9; i++) {
            if (board[r][i] == d) return false;                          // row
            if (board[i][c] == d) return false;                          // column
            if (board[boxRow + i / 3][boxCol + i % 3] == d) return false; // 3x3 box
        }
        return true;
    }
};

class Solution {
public:
    vector<string> letterCombinations(string digits) {
        vector<string> res;
        if (digits.empty()) return res;
        vector<string> mapping = {"", "", "abc", "def", "ghi", "jkl",
                                   "mno", "pqrs", "tuv", "wxyz"};
        string path;
        backtrack(digits, 0, mapping, path, res);
        return res;
    }
private:
    void backtrack(const string& digits, int idx, vector<string>& mapping,
                    string& path, vector<string>& res) {
        if (idx == (int)digits.size()) {
            res.push_back(path);
            return;
        }
        string letters = mapping[digits[idx] - '0'];
        for (char ch : letters) {
            path.push_back(ch);
            backtrack(digits, idx + 1, mapping, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;
        string path;
        backtrack(n, 0, 0, path, res);
        return res;
    }
private:
    void backtrack(int n, int openCount, int closeCount, string& path, vector<string>& res) {
        if ((int)path.size() == 2 * n) {
            res.push_back(path);
            return;
        }
        if (openCount < n) {                 // can still open a new bracket
            path.push_back('(');
            backtrack(n, openCount + 1, closeCount, path, res);
            path.pop_back();
        }
        if (closeCount < openCount) {        // can only close if there's an unmatched '('
            path.push_back(')');
            backtrack(n, openCount, closeCount + 1, path, res);
            path.pop_back();
        }
    }
};

class Solution {
public:
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        if (intervals.empty()) return 0;
        // Sort by end time to always keep the interval that frees up earliest
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });
        int count = 0;
        int prevEnd = intervals[0][1];
        for (int i = 1; i < intervals.size(); i++) {
            if (intervals[i][0] < prevEnd) {
                // Overlaps with previous kept interval -> remove this one
                count++;
            } else {
                prevEnd = intervals[i][1];
            }
        }
        return count;
    }
};

class Solution {
public:
    int findMinArrowShots(vector<vector<int>>& points) {
        if (points.empty()) return 0;
        sort(points.begin(), points.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });
        int arrows = 1;
        long long arrowPos = points[0][1]; // long long to avoid overflow at INT_MAX bounds
        for (int i = 1; i < points.size(); i++) {
            if (points[i][0] > arrowPos) {
                // This balloon isn't hit by the current arrow -> need a new one
                arrows++;
                arrowPos = points[i][1];
            }
        }
        return arrows;
    }
};

class Solution {
public:
    int maxMeetings(vector<int>& start, vector<int>& end) {
        int n = start.size();
        vector<pair<int,int>> meetings(n);
        for (int i = 0; i < n; i++) meetings[i] = {end[i], start[i]};
        sort(meetings.begin(), meetings.end()); // sorts by end time (first element of pair)

        int count = 1;
        int lastEnd = meetings[0].first;
        for (int i = 1; i < n; i++) {
            if (meetings[i].second > lastEnd) { // next meeting starts strictly after last ends
                count++;
                lastEnd = meetings[i].first;
            }
        }
        return count;
    }
};

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> result;
        for (auto& interval : intervals) {
            // If result empty or no overlap with last merged interval, push new
            if (result.empty() || result.back()[1] < interval[0]) {
                result.push_back(interval);
            } else {
                // Overlaps -> extend the end of the last merged interval
                result.back()[1] = max(result.back()[1], interval[1]);
            }
        }
        return result;
    }
};

class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {
        vector<vector<int>> result;
        int i = 0, n = intervals.size();

        // 1. Add all intervals ending strictly before newInterval starts
        while (i < n && intervals[i][1] < newInterval[0]) {
            result.push_back(intervals[i]);
            i++;
        }
        // 2. Merge all intervals overlapping with newInterval
        while (i < n && intervals[i][0] <= newInterval[1]) {
            newInterval[0] = min(newInterval[0], intervals[i][0]);
            newInterval[1] = max(newInterval[1], intervals[i][1]);
            i++;
        }
        result.push_back(newInterval);

        // 3. Add remaining intervals
        while (i < n) {
            result.push_back(intervals[i]);
            i++;
        }
        return result;
    }
};

class Solution {
public:
    bool canJump(vector<int>& nums) {
        int farthest = 0;
        for (int i = 0; i < nums.size(); i++) {
            if (i > farthest) return false; // can't even reach index i
            farthest = max(farthest, i + nums[i]);
        }
        return true;
    }
};

class Solution {
public:
    int jump(vector<int>& nums) {
        int jumps = 0, currEnd = 0, farthest = 0;
        for (int i = 0; i < nums.size() - 1; i++) {
            farthest = max(farthest, i + nums[i]);
            if (i == currEnd) {
                // Must jump now to keep progressing
                jumps++;
                currEnd = farthest;
            }
        }
        return jumps;
    }
};

class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int totalTank = 0, currTank = 0, start = 0;
        for (int i = 0; i < gas.size(); i++) {
            int diff = gas[i] - cost[i];
            totalTank += diff;
            currTank += diff;
            if (currTank < 0) {
                // Can't reach station i+1 from current 'start' -> try starting after i
                start = i + 1;
                currTank = 0;
            }
        }
        return totalTank >= 0 ? start : -1;
    }
};

class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        sort(g.begin(), g.end());
        sort(s.begin(), s.end());
        int child = 0, cookie = 0;
        while (child < g.size() && cookie < s.size()) {
            if (s[cookie] >= g[child]) {
                child++; // this cookie satisfies the current child
            }
            cookie++; // move to next cookie regardless
        }
        return child;
    }
};

class Solution {
public:
    int numRescueBoats(vector<int>& people, int limit) {
        sort(people.begin(), people.end());
        int lo = 0, hi = people.size() - 1;
        int boats = 0;
        while (lo <= hi) {
            if (people[lo] + people[hi] <= limit) {
                lo++; // lightest person can share the boat with the heaviest
            }
            hi--; // heaviest person always leaves on this boat
            boats++;
        }
        return boats;
    }
};

class Solution {
public:
    int twoCitySchedCost(vector<vector<int>>& costs) {
        // Sort by how much cheaper city A is relative to city B
        sort(costs.begin(), costs.end(), [](const vector<int>& a, const vector<int>& b) {
            return (a[0] - a[1]) < (b[0] - b[1]);
        });
        int n = costs.size() / 2;
        int total = 0;
        for (int i = 0; i < costs.size(); i++) {
            total += (i < n) ? costs[i][0] : costs[i][1];
        }
        return total;
    }
};

class Solution {
public:
    string removeDuplicateLetters(string s) {
        vector<int> lastIndex(26, 0);
        for (int i = 0; i < s.size(); i++) lastIndex[s[i] - 'a'] = i;

        vector<bool> inStack(26, false);
        string stk; // used as a stack via push_back/pop_back
        for (int i = 0; i < s.size(); i++) {
            char c = s[i];
            if (inStack[c - 'a']) continue; // already placed, skip

            // Pop chars that are greater than c AND reappear later (safe to remove now)
            while (!stk.empty() && stk.back() > c && lastIndex[stk.back() - 'a'] > i) {
                inStack[stk.back() - 'a'] = false;
                stk.pop_back();
            }
            stk.push_back(c);
            inStack[c - 'a'] = true;
        }
        return stk;
    }
};

class Solution {
public:
    string removeKdigits(string num, int k) {
        string stk;
        for (char c : num) {
            // Pop while top is greater than current digit and removals are left
            while (!stk.empty() && k > 0 && stk.back() > c) {
                stk.pop_back();
                k--;
            }
            stk.push_back(c);
        }
        // If removals remain, remove from the end (largest digits end up there)
        while (k > 0) {
            stk.pop_back();
            k--;
        }
        // Strip leading zeros
        int start = 0;
        while (start < (int)stk.size() - 1 && stk[start] == '0') start++;
        stk = stk.substr(start);
        return stk.empty() ? "0" : stk;
    }
};

class Solution {
public:
    int candy(vector<int>& ratings) {
        int n = ratings.size();
        vector<int> candies(n, 1);

        // Left to right: satisfy the left-neighbor constraint
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) {
                candies[i] = candies[i - 1] + 1;
            }
        }
        // Right to left: satisfy the right-neighbor constraint
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) {
                candies[i] = max(candies[i], candies[i + 1] + 1);
            }
        }

        int total = 0;
        for (int c : candies) total += c;
        return total;
    }
};

class Solution {
public:
    vector<int> partitionLabels(string s) {
        vector<int> lastIndex(26, 0);
        for (int i = 0; i < s.size(); i++) lastIndex[s[i] - 'a'] = i;

        vector<int> result;
        int start = 0, end = 0;
        for (int i = 0; i < s.size(); i++) {
            end = max(end, lastIndex[s[i] - 'a']); // extend partition boundary
            if (i == end) {
                // Every letter seen in this partition is fully contained -> close it
                result.push_back(end - start + 1);
                start = i + 1;
            }
        }
        return result;
    }
};

class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> freq(26, 0);
        for (char t : tasks) freq[t - 'A']++;

        int maxFreq = *max_element(freq.begin(), freq.end());
        int maxCount = 0; // how many tasks share the max frequency
        for (int f : freq) {
            if (f == maxFreq) maxCount++;
        }

        // Idle-slot skeleton: (maxFreq - 1) full cycles of length (n + 1),
        // plus one slot per task that ties for the max frequency in the final row
        int slots = (maxFreq - 1) * (n + 1) + maxCount;
        return max((int)tasks.size(), slots);
    }
};

class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        int n = profits.size();
        vector<pair<int,int>> projects(n); // {capital required, profit}
        for (int i = 0; i < n; i++) projects[i] = {capital[i], profits[i]};
        sort(projects.begin(), projects.end());

        priority_queue<int> maxHeap; // max-heap of profits currently affordable
        int idx = 0;
        for (int i = 0; i < k; i++) {
            // Push all projects that are now affordable with capital w
            while (idx < n && projects[idx].first <= w) {
                maxHeap.push(projects[idx].second);
                idx++;
            }
            if (maxHeap.empty()) break; // no affordable project remains
            w += maxHeap.top(); // greedily take the most profitable affordable project
            maxHeap.pop();
        }
        return w;
    }
};

class Solution {
public:
    string reorganizeString(string s) {
        vector<int> freq(26, 0);
        for (char c : s) freq[c - 'a']++;

        int maxFreq = *max_element(freq.begin(), freq.end());
        if (maxFreq > (int)(s.size() + 1) / 2) return ""; // impossible to arrange

        // Max-heap of {frequency, character}
        priority_queue<pair<int,char>> maxHeap;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) maxHeap.push({freq[i], (char)('a' + i)});
        }

        string result;
        while (maxHeap.size() >= 2) {
            auto [f1, c1] = maxHeap.top(); maxHeap.pop();
            auto [f2, c2] = maxHeap.top(); maxHeap.pop();
            // Place the two most frequent remaining characters back-to-back
            result += c1;
            result += c2;
            if (--f1 > 0) maxHeap.push({f1, c1});
            if (--f2 > 0) maxHeap.push({f2, c2});
        }
        if (!maxHeap.empty()) {
            auto [f, c] = maxHeap.top();
            if (f > 1) return ""; // safety net; shouldn't trigger given the earlier check
            result += c;
        }
        return result;
    }
};

class Solution {
public:
    int hammingWeight(uint32_t n) {
        int count = 0;
        while (n) {
            n &= (n - 1);   // clears the lowest set bit
            count++;
        }
        return count;
    }
};

class Solution {
public:
    vector<int> countBits(int n) {
        vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i >> 1] + (i & 1);   // reuse previously computed result
        }
        return dp;
    }
};

class Solution {
public:
    bool isPowerOfTwo(int n) {
        if (n <= 0) return false;
        return (n & (n - 1)) == 0;   // true only if exactly one bit is set
    }
};

class Solution {
public:
    bool isPowerOfFour(int n) {
        if (n <= 0) return false;
        bool isPowerOfTwo = (n & (n - 1)) == 0;
        bool atEvenPosition = (n & 0xAAAAAAAA) == 0;  // 0xAAAAAAAA has 1s at odd bit positions
        return isPowerOfTwo && atEvenPosition;
    }
};

class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int num : nums) {
            result ^= num;   // duplicates cancel out (x ^ x = 0)
        }
        return result;
    }
};

class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int bit = 0; bit < 32; bit++) {
            int sum = 0;
            for (int num : nums) {
                sum += (num >> bit) & 1;   // count how many numbers have this bit set
            }
            if (sum % 3 != 0) {
                result |= (1 << bit);      // this bit belongs to the unique number
            }
        }
        return result;
    }
};

class Solution {
public:
    vector<int> singleNumber(vector<int>& nums) {
        int xorAll = 0;
        for (int num : nums) xorAll ^= num;   // xorAll = a ^ b

        // isolate the lowest set bit — a distinguishing bit between a and b
        int diffBit = xorAll & (-xorAll);

        int a = 0, b = 0;
        for (int num : nums) {
            if (num & diffBit) a ^= num;      // group where this bit is set
            else b ^= num;                    // group where this bit is unset
        }
        return {a, b};
    }
};

class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int result = nums.size();          // account for index n up front
        for (int i = 0; i < nums.size(); i++) {
            result ^= i ^ nums[i];         // cancel index i with value nums[i]
        }
        return result;
    }
};

class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> res;

        for (int mask = 0; mask < (1 << n); mask++) {   // 2^n masks total
            vector<int> subset;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) {                   // bit i set -> include nums[i]
                    subset.push_back(nums[i]);
                }
            }
            res.push_back(subset);
        }
        return res;
    }
};

class Solution {
public:
    int subsetXORSum(vector<int>& nums) {
        int n = nums.size();
        int totalSum = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            int xorTotal = 0;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) {
                    xorTotal ^= nums[i];   // build XOR for this subset
                }
            }
            totalSum += xorTotal;
        }
        return totalSum;
    }

    // O(n) closed-form alternative:
    // int subsetXORSum(vector<int>& nums) {
    //     int orAll = 0;
    //     for (int num : nums) orAll |= num;
    //     return orAll << (nums.size() - 1);
    // }
};

class Solution {
public:
    int getSum(int a, int b) {
        while (b != 0) {
            int carry = (unsigned int)(a & b) << 1;  // bits where both are 1 produce a carry
            a = a ^ b;                                // sum without carry
            b = carry;                                // carry becomes the new "b" to add
        }
        return a;
    }
};

class Solution {
public:
    int divide(int dividend, int divisor) {
        if (dividend == INT_MIN && divisor == -1) return INT_MAX;  // overflow guard

        long long dvd = labs((long long)dividend);
        long long dvs = labs((long long)divisor);
        long long quotient = 0;

        while (dvd >= dvs) {
            long long temp = dvs, multiple = 1;
            while (dvd >= (temp << 1)) {   // double divisor while it still fits
                temp <<= 1;
                multiple <<= 1;
            }
            dvd -= temp;                   // subtract the largest fitting chunk
            quotient += multiple;
        }

        bool negative = (dividend < 0) ^ (divisor < 0);
        return negative ? -quotient : quotient;
    }
};

class Solution {
public:
    int rangeBitwiseAnd(int left, int right) {
        int shift = 0;
        while (left != right) {
            left >>= 1;
            right >>= 1;
            shift++;               // count how many bits we dropped
        }
        return left << shift;      // restore the common prefix, rest are 0s
    }
};

class Solution {
public:
    int findComplement(int num) {
        int mask = 1;
        // build mask with same bit-length as num, e.g. num=101 -> mask=111
        while (mask < num) {
            mask = (mask << 1) | 1;
        }
        return num ^ mask;   // flips every bit within that range
    }
};

class Solution {
public:
    uint32_t reverseBits(uint32_t n) {
        uint32_t result = 0;
        for (int i = 0; i < 32; i++) {
            result <<= 1;              // make room for the next bit
            result |= (n & 1);         // append n's lowest bit to result
            n >>= 1;                   // move to the next bit of n
        }
        return result;
    }
};

class Solution {
    struct TrieNode {
        TrieNode* child[2] = {nullptr, nullptr};
    };

    TrieNode* root = new TrieNode();

    void insert(int num) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (!node->child[bit]) node->child[bit] = new TrieNode();
            node = node->child[bit];
        }
    }

    int queryMaxXor(int num) {
        TrieNode* node = root;
        int result = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int wantedBit = 1 - bit;              // prefer the opposite bit to maximize XOR
            if (node->child[wantedBit]) {
                result |= (1 << i);               // this bit differs -> contributes to XOR
                node = node->child[wantedBit];
            } else {
                node = node->child[bit];          // forced to take the same bit
            }
        }
        return result;
    }

public:
    int findMaximumXOR(vector<int>& nums) {
        for (int num : nums) insert(num);

        int maxXor = 0;
        for (int num : nums) {
            maxXor = max(maxXor, queryMaxXor(num));
        }
        return maxXor;
    }
};

class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        int islands = 0;

        function<void(int,int)> dfs = [&](int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '1') return;
            grid[r][c] = '0'; // mark visited by sinking the land
            dfs(r + 1, c); dfs(r - 1, c);
            dfs(r, c + 1); dfs(r, c - 1);
        };

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '1') {
                    islands++;
                    dfs(r, c); // sink entire island so it's never counted again
                }
            }
        }
        return islands;
    }
};

class Solution {
public:
    int maxAreaOfIsland(vector<vector<int>>& grid) {
        int rows = grid.size(), cols = grid[0].size();

        function<int(int,int)> dfs = [&](int r, int c) -> int {
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != 1) return 0;
            grid[r][c] = 0; // sink
            return 1 + dfs(r+1, c) + dfs(r-1, c) + dfs(r, c+1) + dfs(r, c-1);
        };

        int best = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (grid[r][c] == 1)
                    best = max(best, dfs(r, c));
        return best;
    }
};

class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int oldColor = image[sr][sc];
        if (oldColor == color) return image; // avoid infinite recursion on no-op

        int rows = image.size(), cols = image[0].size();
        function<void(int,int)> dfs = [&](int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] != oldColor) return;
            image[r][c] = color;
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1);
        };
        dfs(sr, sc);
        return image;
    }
};

class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int rows = board.size(), cols = board[0].size();

        function<void(int,int)> dfs = [&](int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != 'O') return;
            board[r][c] = '#'; // temp mark = safe, border-connected
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1);
        };

        // Step 1: protect every 'O' reachable from the border
        for (int r = 0; r < rows; r++) { dfs(r, 0); dfs(r, cols - 1); }
        for (int c = 0; c < cols; c++) { dfs(0, c); dfs(rows - 1, c); }

        // Step 2: flip surrounded 'O' -> 'X', restore safe '#' -> 'O'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') board[r][c] = 'X';
                else if (board[r][c] == '#') board[r][c] = 'O';
            }
        }
    }
};

class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int rows = heights.size(), cols = heights[0].size();
        vector<vector<bool>> pacific(rows, vector<bool>(cols, false));
        vector<vector<bool>> atlantic(rows, vector<bool>(cols, false));

        function<void(int,int,vector<vector<bool>>&)> dfs = [&](int r, int c, vector<vector<bool>>& visited) {
            visited[r][c] = true;
            int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (visited[nr][nc] || heights[nr][nc] < heights[r][c]) continue; // must flow uphill (reversed)
                dfs(nr, nc, visited);
            }
        };

        for (int r = 0; r < rows; r++) { dfs(r, 0, pacific); dfs(r, cols - 1, atlantic); }
        for (int c = 0; c < cols; c++) { dfs(0, c, pacific); dfs(rows - 1, c, atlantic); }

        vector<vector<int>> result;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (pacific[r][c] && atlantic[r][c])
                    result.push_back({r, c});
        return result;
    }
};

class DSU {
    vector<int> parent, rank_;
public:
    DSU(int n) : parent(n), rank_(n, 0) {
        iota(parent.begin(), parent.end(), 0); // each node is its own parent initially
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]); // path compression
        return parent[x];
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank_[ra] < rank_[rb]) swap(ra, rb);
        parent[rb] = ra;
        if (rank_[ra] == rank_[rb]) rank_[ra]++;
    }
};

class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
        int n = isConnected.size();
        DSU dsu(n);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (isConnected[i][j] == 1)
                    dsu.unite(i, j);

        unordered_set<int> roots;
        for (int i = 0; i < n; i++) roots.insert(dsu.find(i));
        return roots.size();
    }
};

class Solution {
public:
    vector<int> findRedundantConnection(vector<vector<int>>& edges) {
        int n = edges.size();
        vector<int> parent(n + 1);
        iota(parent.begin(), parent.end(), 0);

        function<int(int)> find = [&](int x) {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } // path halving
            return x;
        };

        for (auto& e : edges) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra == rb) return e; // this edge closes a cycle -> it's the answer
            parent[ra] = rb;
        }
        return {}; // unreachable given problem constraints
    }
};

class Solution {
public:
    int countComponents(int n, vector<vector<int>>& edges) {
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        int components = n; // start assuming every node is isolated

        function<int(int)> find = [&](int x) {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        };

        for (auto& e : edges) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra != rb) {
                parent[ra] = rb;
                components--; // merging two groups reduces total component count
            }
        }
        return components;
    }
};

class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> adj(numCourses);
        vector<int> indegree(numCourses, 0);

        for (auto& p : prerequisites) {
            adj[p[1]].push_back(p[0]); // edge: prereq -> dependent course
            indegree[p[0]]++;
        }

        queue<int> q;
        for (int i = 0; i < numCourses; i++)
            if (indegree[i] == 0) q.push(i); // courses with no prerequisite can start immediately

        int processed = 0;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            processed++;
            for (int next : adj[cur])
                if (--indegree[next] == 0) q.push(next);
        }
        return processed == numCourses; // if not all processed, a cycle blocked some courses
    }
};

class Solution {
public:
    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> adj(numCourses);
        vector<int> indegree(numCourses, 0);

        for (auto& p : prerequisites) {
            adj[p[1]].push_back(p[0]);
            indegree[p[0]]++;
        }

        queue<int> q;
        for (int i = 0; i < numCourses; i++)
            if (indegree[i] == 0) q.push(i);

        vector<int> order;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            order.push_back(cur);
            for (int next : adj[cur])
                if (--indegree[next] == 0) q.push(next);
        }
        return order.size() == numCourses ? order : vector<int>{};
    }
};

class Solution {
public:
    string findOrder(vector<string>& words) {
        unordered_map<char, unordered_set<char>> adj;
        unordered_map<char, int> indegree;
        for (auto& w : words)
            for (char c : w) indegree[c] = 0; // ensure every seen letter is a node

        for (int i = 0; i + 1 < words.size(); i++) {
            string &w1 = words[i], &w2 = words[i + 1];
            int minLen = min(w1.size(), w2.size());
            bool foundDiff = false;
            for (int j = 0; j < minLen; j++) {
                if (w1[j] != w2[j]) {
                    if (!adj[w1[j]].count(w2[j])) {
                        adj[w1[j]].insert(w2[j]);
                        indegree[w2[j]]++;
                    }
                    foundDiff = true;
                    break;
                }
            }
            // invalid case: "abc" before "ab" -> prefix must come first
            if (!foundDiff && w1.size() > w2.size()) return "";
        }

        queue<char> q;
        for (auto& [ch, deg] : indegree) if (deg == 0) q.push(ch);

        string order;
        while (!q.empty()) {
            char cur = q.front(); q.pop();
            order += cur;
            for (char next : adj[cur])
                if (--indegree[next] == 0) q.push(next);
        }
        return order.size() == indegree.size() ? order : ""; // cycle -> invalid ordering
    }
};

class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        queue<pair<int,int>> q;
        int freshCount = 0;

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) q.push({r, c}); // all rotten oranges start together
                else if (grid[r][c] == 1) freshCount++;
            }

        if (freshCount == 0) return 0;

        int minutes = 0;
        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
        while (!q.empty()) {
            int levelSize = q.size();
            bool rottedAny = false;
            for (int i = 0; i < levelSize; i++) {
                auto [r, c] = q.front(); q.pop();
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != 1) continue;
                    grid[nr][nc] = 2;
                    freshCount--;
                    rottedAny = true;
                    q.push({nr, nc});
                }
            }
            if (rottedAny) minutes++;
        }
        return freshCount == 0 ? minutes : -1;
    }
};

class Solution {
public:
    vector<vector<int>> updateMatrix(vector<vector<int>>& mat) {
        int rows = mat.size(), cols = mat[0].size();
        vector<vector<int>> dist(rows, vector<int>(cols, -1));
        queue<pair<int,int>> q;

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (mat[r][c] == 0) { dist[r][c] = 0; q.push({r, c}); }

        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[r][c] + 1;
                q.push({nr, nc});
            }
        }
        return dist;
    }
};

class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        if (!dict.count(endWord)) return 0;

        queue<string> q;
        q.push(beginWord);
        int steps = 1;

        while (!q.empty()) {
            int levelSize = q.size();
            for (int i = 0; i < levelSize; i++) {
                string word = q.front(); q.pop();
                if (word == endWord) return steps;

                for (int pos = 0; pos < word.size(); pos++) {
                    char original = word[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        word[pos] = c;
                        if (dict.count(word)) {
                            dict.erase(word); // remove so it's never re-queued (acts as visited)
                            q.push(word);
                        }
                    }
                    word[pos] = original; // restore before trying next position
                }
            }
            steps++;
        }
        return 0;
    }
};

class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        vector<vector<pair<int,int>>> adj(n + 1); // adj[u] = {v, weight}
        for (auto& t : times) adj[t[0]].push_back({t[1], t[2]});

        vector<int> dist(n + 1, INT_MAX);
        dist[k] = 0;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq; // min-heap by distance
        pq.push({0, k});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue; // stale entry, a shorter path was already found
            for (auto& [v, w] : adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }

        int maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] == INT_MAX) return -1; // unreachable node
            maxDist = max(maxDist, dist[i]);
        }
        return maxDist;
    }
};

class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        int rows = heights.size(), cols = heights[0].size();
        vector<vector<int>> effort(rows, vector<int>(cols, INT_MAX));
        effort[0][0] = 0;

        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq; // {effort, r, c}
        pq.push({0, 0, 0});
        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};

        while (!pq.empty()) {
            auto [e, r, c] = pq.top(); pq.pop();
            if (r == rows - 1 && c == cols - 1) return e; // reached destination
            if (e > effort[r][c]) continue;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                int newEffort = max(e, abs(heights[nr][nc] - heights[r][c])); // bottleneck, not sum
                if (newEffort < effort[nr][nc]) {
                    effort[nr][nc] = newEffort;
                    pq.push({newEffort, nr, nc});
                }
            }
        }
        return 0;
    }
};

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        vector<int> dist(n, INT_MAX);
        dist[src] = 0;

        for (int round = 0; round <= k; round++) { // k stops = k+1 edges max
            vector<int> next = dist; // snapshot so updates don't chain within the same round
            for (auto& f : flights) {
                int u = f[0], v = f[1], w = f[2];
                if (dist[u] != INT_MAX && dist[u] + w < next[v])
                    next[v] = dist[u] + w;
            }
            dist = next;
        }
        return dist[dst] == INT_MAX ? -1 : dist[dst];
    }
};

class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int n = points.size();
        vector<bool> visited(n, false);
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq; // {cost, point index}
        pq.push({0, 0});

        int totalCost = 0, edgesUsed = 0;
        while (edgesUsed < n) {
            auto [cost, u] = pq.top(); pq.pop();
            if (visited[u]) continue; // stale entry
            visited[u] = true;
            totalCost += cost;
            edgesUsed++;

            for (int v = 0; v < n; v++) {
                if (!visited[v]) {
                    int dist = abs(points[u][0] - points[v][0]) + abs(points[u][1] - points[v][1]);
                    pq.push({dist, v});
                }
            }
        }
        return totalCost;
    }
};

class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> color(n, -1); // -1 = uncolored

        function<bool(int,int)> dfs = [&](int node, int c) -> bool {
            color[node] = c;
            for (int next : graph[node]) {
                if (color[next] == -1) {
                    if (!dfs(next, 1 - c)) return false; // flip color for neighbor
                } else if (color[next] == c) {
                    return false; // same color on both ends of an edge -> conflict
                }
            }
            return true;
        };

        for (int i = 0; i < n; i++)
            if (color[i] == -1 && !dfs(i, 0))
                return false;
        return true;
    }
};

class Node {
public:
    int val;
    vector<Node*> neighbors;
    Node(int _val) { val = _val; }
};

class Solution {
public:
    Node* cloneGraph(Node* node) {
        if (!node) return nullptr;
        unordered_map<Node*, Node*> cloned; // original -> clone

        function<Node*(Node*)> dfs = [&](Node* orig) -> Node* {
            if (cloned.count(orig)) return cloned[orig]; // already cloned, avoids infinite recursion on cycles

            Node* copy = new Node(orig->val);
            cloned[orig] = copy; // register BEFORE recursing into neighbors

            for (Node* neighbor : orig->neighbors)
                copy->neighbors.push_back(dfs(neighbor));

            return copy;
        };

        return dfs(node);
    }
};

class Solution {
public:
    int climbStairs(int n) {
        if (n <= 1) return 1;
        int prev2 = 1, prev1 = 1; // ways to reach step 0 and step 1
        for (int i = 2; i <= n; i++) {
            int cur = prev1 + prev2;
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
};

class Solution {
public:
    int rob(vector<int>& nums) {
        int prev2 = 0, prev1 = 0; // dp[i-2], dp[i-1]
        for (int num : nums) {
            int cur = max(prev1, prev2 + num); // skip house i or rob it
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
};

class Solution {
public:
    int robLine(vector<int>& nums, int start, int end) {
        int prev2 = 0, prev1 = 0;
        for (int i = start; i <= end; i++) {
            int cur = max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }

    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        // Case 1: exclude last house | Case 2: exclude first house
        return max(robLine(nums, 0, n - 2), robLine(nums, 1, n - 1));
    }
};

class Solution {
public:
    int numDecodings(string s) {
        int n = s.size();
        if (n == 0 || s[0] == '0') return 0;
        int prev2 = 1, prev1 = 1; // dp[0] = 1 (empty prefix), dp[1] = 1
        for (int i = 2; i <= n; i++) {
            int cur = 0;
            int oneDigit = s[i - 1] - '0';
            int twoDigit = (s[i - 2] - '0') * 10 + oneDigit;
            if (oneDigit >= 1) cur += prev1;                     // single digit decode
            if (twoDigit >= 10 && twoDigit <= 26) cur += prev2;  // two digit decode
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
};

class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<int> dp(n, 1); // first row: exactly 1 way to reach each cell
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] += dp[j - 1]; // dp[j] currently holds dp[i-1][j]
            }
        }
        return dp[n - 1];
    }
};

class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<long> dp(n, 0);
        dp[0] = (grid[0][0] == 0) ? 1 : 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp[j] = 0; // obstacle blocks this cell entirely
                } else if (j > 0) {
                    dp[j] += dp[j - 1]; // add paths coming from the left
                }
            }
        }
        return (int)dp[n - 1];
    }
};

class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<int> dp(n, INT_MAX);
        dp[0] = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (j == 0) dp[j] = dp[j] + grid[i][j];          // only from top
                else        dp[j] = grid[i][j] + min(dp[j], dp[j - 1]); // min(top, left)
            }
        }
        return dp[n - 1];
    }
};

class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total % 2 != 0) return false;
        int target = total / 2;
        vector<bool> dp(target + 1, false);
        dp[0] = true; // sum 0 is always achievable
        for (int num : nums) {
            for (int s = target; s >= num; s--) { // backwards: use num at most once
                dp[s] = dp[s] || dp[s - num];
            }
        }
        return dp[target];
    }
};

class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (abs(target) > total || (total + target) % 2 != 0) return 0;
        int P = (total + target) / 2; // subset getting '+' must sum to P
        vector<int> dp(P + 1, 0);
        dp[0] = 1;
        for (int num : nums) {
            for (int s = P; s >= num; s--) {
                dp[s] += dp[s - num]; // count ways, not just reachability
            }
        }
        return dp[P];
    }
};

class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, INT_MAX);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++) {
            for (int coin : coins) {
                if (coin <= a && dp[a - coin] != INT_MAX) {
                    dp[a] = min(dp[a], dp[a - coin] + 1);
                }
            }
        }
        return dp[amount] == INT_MAX ? -1 : dp[amount];
    }
};

class Solution {
public:
    int change(int amount, vector<int>& coins) {
        vector<int> dp(amount + 1, 0);
        dp[0] = 1; // one way to make amount 0: use nothing
        for (int coin : coins) {
            for (int a = coin; a <= amount; a++) { // coin outer -> combinations, not permutations
                dp[a] += dp[a - coin];
            }
        }
        return dp[amount];
    }
};

class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size(), n = text2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (text1[i - 1] == text2[j - 1])
                    dp[i][j] = dp[i - 1][j - 1] + 1;              // extend match
                else
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);   // skip a char
            }
        }
        return dp[m][n];
    }
};

class Solution {
public:
    int minDistance(string word1, string word2) {
        int m = word1.size(), n = word2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i <= m; i++) dp[i][0] = i; // delete all of word1
        for (int j = 0; j <= n; j++) dp[0][j] = j; // insert all of word2
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1[i - 1] == word2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1]; // no operation needed
                } else {
                    dp[i][j] = 1 + min({dp[i - 1][j - 1],  // replace
                                         dp[i - 1][j],      // delete
                                         dp[i][j - 1]});    // insert
                }
            }
        }
        return dp[m][n];
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        vector<int> tails; // tails[i] = smallest tail of an increasing subsequence of length i+1
        for (int num : nums) {
            auto it = lower_bound(tails.begin(), tails.end(), num);
            if (it == tails.end()) tails.push_back(num); // extends longest subsequence so far
            else *it = num;                               // keeps tail as small as possible
        }
        return tails.size();
    }
};

class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        if (n == 0) return "";
        vector<vector<bool>> dp(n, vector<bool>(n, false));
        int start = 0, maxLen = 1;
        for (int i = 0; i < n; i++) dp[i][i] = true; // every single char is a palindrome
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s[i] == s[j] && (len == 2 || dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                    if (len > maxLen) { maxLen = len; start = i; }
                }
            }
        }
        return s.substr(start, maxLen);
    }
};

class Solution {
public:
    int countSubstrings(string s) {
        int n = s.size(), count = 0;
        vector<vector<bool>> dp(n, vector<bool>(n, false));
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s[i] == s[j] && (len <= 2 || dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                    count++;
                }
            }
        }
        return count;
    }
};

class Solution {
public:
    int longestPalindromeSubseq(string s) {
        int n = s.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1; // single character is a palindrome of length 1
            for (int j = i + 1; j < n; j++) {
                if (s[i] == s[j]) dp[i][j] = dp[i + 1][j - 1] + 2; // include both ends
                else               dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]); // drop one end
            }
        }
        return dp[0][n - 1];
    }
};

class Solution {
public:
    int maxCoins(vector<int>& nums) {
        int n = nums.size();
        vector<int> balloons(n + 2, 1); // padded with virtual balloons of value 1
        for (int i = 0; i < n; i++) balloons[i + 1] = nums[i];

        vector<vector<int>> dp(n + 2, vector<int>(n + 2, 0));
        for (int len = 1; len <= n; len++) {           // len = size of open interval (l, r)
            for (int l = 1; l + len - 1 <= n; l++) {
                int r = l + len - 1;
                for (int k = l; k <= r; k++) {          // k = LAST balloon burst in (l-1, r+1)
                    int coins = balloons[l - 1] * balloons[k] * balloons[r + 1]
                                + dp[l][k - 1] + dp[k + 1][r];
                    dp[l][r] = max(dp[l][r], coins);
                }
            }
        }
        return dp[1][n];
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        if (prices.empty()) return 0;
        int held = INT_MIN, sold = 0, rest = 0;
        for (int price : prices) {
            int prevSold = sold;
            sold = held + price;             // sell today
            held = max(held, rest - price);  // keep holding or buy today
            rest = max(rest, prevSold);       // stay resting or come off cooldown
        }
        return max(sold, rest);
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int buy1 = INT_MIN, sell1 = 0, buy2 = INT_MIN, sell2 = 0;
        for (int price : prices) {
            buy1  = max(buy1, -price);         // best cost after 1st buy
            sell1 = max(sell1, buy1 + price);  // best profit after 1st sell
            buy2  = max(buy2, sell1 - price);  // best net after 2nd buy
            sell2 = max(sell2, buy2 + price);  // best profit after 2nd sell
        }
        return sell2;
    }
};
